function createEffectScheduler() {
  const layoutQueue = [];
  const passiveQueue = [];

  return {
    scheduleLayout(fn) {
      layoutQueue.push(fn);
    },
    schedulePassive(fn) {
      passiveQueue.push(fn);
    },
    flushLayout() {
      const executed = [];
      while (layoutQueue.length > 0) {
        const fn = layoutQueue.shift();
        executed.push(fn());
      }
      return executed;
    },
    async flushPassive() {
      // Yield to macrotask/microtask to simulate post-paint delivery
      await new Promise(r => setTimeout(r, 0));
      const executed = [];
      while (passiveQueue.length > 0) {
        const fn = passiveQueue.shift();
        executed.push(fn());
      }
      return executed;
    }
  };
}
